compile.workshop:
variables {
    global:
        0: t
        1: s
}

rule ("repro") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(s, String Slice(Add(Modulo(Global.t, 60), 100), 1, 2));
    }
}

